// SynthesizeChangelog generates a compressed Debian changelog conforming to Debian Policy §12.7.
// Returns (compressedBytes, error). If changelog is disabled ("none", "false"), returns (nil, nil).
func SynthesizeChangelog(cfg *spec.CraftpackConfig, workspaceDir, version string, modTime time.Time) ([]byte, error) {
	if cfg == nil {
		return nil, errors.New("craftpack config cannot be nil")
	}

	mode := strings.ToLower(strings.TrimSpace(cfg.Changelog))
	if mode == "none" || mode == "false" || mode == "disabled" {
		return nil, nil
	}

	var rawContent []byte

	if mode != "" && mode != "auto" {
		// Custom changelog file path
		filePath := cfg.Changelog
		if !filepath.IsAbs(filePath) && workspaceDir != "" {
			filePath = filepath.Join(workspaceDir, filePath)
		}
		data, err := os.ReadFile(filePath)
		if err != nil {
			return nil, fmt.Errorf("failed to read changelog file '%s': %w", cfg.Changelog, err)
		}
		// If already gzip compressed
		if len(data) >= 2 && data[0] == 0x1f && data[1] == 0x8b {
			return data, nil
		}
		rawContent = data
	} else {
		// Dynamic Git changelog synthesis
		rawContent = GenerateGitChangelog(cfg, workspaceDir, version, modTime)
	}

	return CompressChangelog(rawContent)
}

// CompressChangelog compresses changelog bytes using gzip level 9 with zeroed ModTime and OS 255.
func CompressChangelog(plainContent []byte) ([]byte, error) {
	var buf bytes.Buffer
	gw, err := gzip.NewWriterLevel(&buf, gzip.BestCompression)
	if err != nil {
		return nil, fmt.Errorf("failed to create gzip writer: %w", err)
	}
	gw.Header.ModTime = time.Time{} // Zero timestamp per Debian Policy §12.1 and Reproducible Builds
	gw.Header.OS = 255              // Neutral OS
	if _, err := gw.Write(plainContent); err != nil {
		return nil, fmt.Errorf("failed to compress changelog: %w", err)
	}
	if err := gw.Close(); err != nil {
		return nil, fmt.Errorf("failed to close gzip writer: %w", err)
	}
	return buf.Bytes(), nil
}

type gitChangelogEntry struct {
	pkgName    string
	version    string
	maintainer string
	timestamp  time.Time
	commits    []string
}

// GenerateGitChangelog extracts Git history and formats Debian changelog entries.
func GenerateGitChangelog(cfg *spec.CraftpackConfig, workspaceDir, version string, modTime time.Time) []byte {
	pkgName := strings.TrimSpace(cfg.Name)
	if pkgName == "" {
		pkgName = "package"
	}
	maintainer := strings.TrimSpace(cfg.Maintainer)
	if maintainer == "" {
		maintainer = "Package Maintainer <maintainer@example.org>"
	}
	cleanVersion := NormalizeVersion(version)
	if cleanVersion == "" {
		cleanVersion = "0.1.0"
	}

	fallbackTime := modTime.UTC()
	if fallbackTime.IsZero() {
		fallbackTime = time.Now().UTC()
	}

	// Check if workspaceDir is inside a git repo
	gitDir := workspaceDir
	if gitDir == "" {
		gitDir = "."
	}

	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
	defer cancel()

	checkCmd := exec.CommandContext(ctx, "git", "-C", gitDir, "rev-parse", "--is-inside-work-tree")
	if err := checkCmd.Run(); err != nil {
		dateStr := fallbackTime.Format("Mon, 02 Jan 2006 15:04:05 -0700")
		return formatSingleChangelogEntry(pkgName, cleanVersion, maintainer, dateStr, []string{"Release " + cleanVersion + "."})
	}

	// Fetch tags sorted in reverse version order
	tagsCmd := exec.CommandContext(ctx, "git", "-C", gitDir, "tag", "-l", "--sort=-version:refname", "v*", "*.*.*")
	tagsOut, err := tagsCmd.Output()
	if err != nil || len(bytes.TrimSpace(tagsOut)) == 0 {
		commits := getGitCommits(gitDir, "HEAD")
		date := getGitTimestamp(gitDir, "HEAD", fallbackTime)
		if len(commits) == 0 {
			commits = []string{"Release " + cleanVersion + "."}
		}
		dateStr := date.Format("Mon, 02 Jan 2006 15:04:05 -0700")
		return formatSingleChangelogEntry(pkgName, cleanVersion, maintainer, dateStr, commits)
	}

	rawTags := strings.Split(strings.TrimSpace(string(tagsOut)), "\n")
	var tags []string
	for _, t := range rawTags {
		trimmed := strings.TrimSpace(t)
		if trimmed != "" {
			tags = append(tags, trimmed)
		}
	}

	var entries []gitChangelogEntry

	// Check if cleanVersion matches any tag
	matchIdx := -1
	for i, tag := range tags {
		if cleanVersion == NormalizeVersion(tag) {
			matchIdx = i
			break
		}
	}

	if matchIdx != -1 {
		// Target version is an existing tag: output only from that tag downwards
		for i := matchIdx; i < len(tags); i++ {
			tag := tags[i]
			tagVer := NormalizeVersion(tag)
			var commits []string
			if i+1 < len(tags) {
				commits = getGitCommits(gitDir, tags[i+1]+".."+tag)
			} else {
				commits = getGitCommits(gitDir, tag)
			}
			date := getGitTimestamp(gitDir, tag, fallbackTime)
			if len(commits) == 0 {
				commits = []string{"Release " + tagVer + "."}
			}
			entries = append(entries, gitChangelogEntry{
				pkgName:    pkgName,
				version:    tagVer,
				maintainer: maintainer,
				timestamp:  date,
				commits:    commits,
			})
		}
	} else {
		// New unreleased version: build top entry from HEAD
		topCommits := getGitCommits(gitDir, tags[0]+"..HEAD")
		topDate := getGitTimestamp(gitDir, "HEAD", fallbackTime)
		if len(topCommits) == 0 {
			topCommits = []string{"Release " + cleanVersion + "."}
		}
		entries = append(entries, gitChangelogEntry{
			pkgName:    pkgName,
			version:    cleanVersion,
			maintainer: maintainer,
			timestamp:  topDate,
			commits:    topCommits,
		})

		// Include only tags whose version is <= cleanVersion
		for i, tag := range tags {
			tagVer := NormalizeVersion(tag)
			if compareVersions(tagVer, cleanVersion) > 0 {
				continue
			}
			var commits []string
			if i+1 < len(tags) {
				commits = getGitCommits(gitDir, tags[i+1]+".."+tag)
			} else {
				commits = getGitCommits(gitDir, tag)
			}
			date := getGitTimestamp(gitDir, tag, fallbackTime)
			if len(commits) == 0 {
				commits = []string{"Release " + tagVer + "."}
			}
			entries = append(entries, gitChangelogEntry{
				pkgName:    pkgName,
				version:    tagVer,
				maintainer: maintainer,
				timestamp:  date,
				commits:    commits,
			})
		}
	}

	// Enforce strict timestamp monotonicity: entries[i] must be strictly after entries[i+1]
	for i := len(entries) - 2; i >= 0; i-- {
		if !entries[i].timestamp.After(entries[i+1].timestamp) {
			entries[i].timestamp = entries[i+1].timestamp.Add(1 * time.Second)
		}
	}

	var b strings.Builder
	for i, entry := range entries {
		if i > 0 {
			b.WriteString("\n")
		}
		dateStr := entry.timestamp.Format("Mon, 02 Jan 2006 15:04:05 -0700")
		b.Write(formatSingleChangelogEntry(entry.pkgName, entry.version, entry.maintainer, dateStr, entry.commits))
	}

	return []byte(b.String())
}

func getGitTimestamp(gitDir, revision string, fallback time.Time) time.Time {
	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
	defer cancel()

	cmd := exec.CommandContext(ctx, "git", "-C", gitDir, "log", "-1", "--format=%cI", revision)
	out, err := cmd.Output()
	if err == nil {
		trimmed := strings.TrimSpace(string(out))
		if t, err := time.Parse(time.RFC3339, trimmed); err == nil {
			return t.UTC()
		}
	}
	return fallback
}

func getGitCommits(gitDir, revRange string) []string {
	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
	defer cancel()

	cmd := exec.CommandContext(ctx, "git", "-C", gitDir, "log", "--no-merges", "--pretty=format:%s", revRange)
	out, err := cmd.Output()
	if err != nil {
		return nil
	}

	var lines []string
	for _, l := range strings.Split(string(out), "\n") {
		trimmed := strings.TrimSpace(l)
		if trimmed != "" {
			lines = append(lines, trimmed)
		}
	}
	return lines
}

func parseVersionTriplet(v string) (int, int, int) {
	clean := NormalizeVersion(v)
	if idx := strings.IndexAny(clean, "-+"); idx != -1 {
		clean = clean[:idx]
	}
	parts := strings.Split(clean, ".")
	var maj, min, patch int
	if len(parts) > 0 {
		fmt.Sscanf(parts[0], "%d", &maj)
	}
	if len(parts) > 1 {
		fmt.Sscanf(parts[1], "%d", &min)
	}
	if len(parts) > 2 {
		fmt.Sscanf(parts[2], "%d", &patch)
	}
	return maj, min, patch
}

func compareVersions(v1, v2 string) int {
	maj1, min1, patch1 := parseVersionTriplet(v1)
	maj2, min2, patch2 := parseVersionTriplet(v2)
	if maj1 != maj2 {
		if maj1 > maj2 {
			return 1
		}
		return -1
	}
	if min1 != min2 {
		if min1 > min2 {
			return 1
		}
		return -1
	}
	if patch1 != patch2 {
		if patch1 > patch2 {
			return 1
		}
		return -1
	}
	return 0
}

func formatSingleChangelogEntry(pkg, ver, maintainer, date string, commits []string) []byte {
	var b strings.Builder
	// Line 1: package (version) distribution(s); urgency=urgency
	fmt.Fprintf(&b, "%s (%s) unstable; urgency=medium\n\n", pkg, ver)

	// Items: 2 spaces, bullet (* ), items wrapped if long
	for _, c := range commits {
		formattedItem := wrapChangelogItem(c)
		b.WriteString(formattedItem)
		b.WriteString("\n")
	}

	// Footer: 1 leading space, 2 dashes, maintainer, 2 spaces, date per Debian Policy §12.7
	fmt.Fprintf(&b, "\n -- %s  %s\n", maintainer, date)
	return []byte(b.String())
}

func wrapChangelogItem(item string) string {
	prefix := "  * "
	continuationPrefix := "    "
	maxLineLen := 78

	words := strings.Fields(item)
	if len(words) == 0 {
		return prefix
	}

	var lines []string
	current := prefix + words[0]

	for _, w := range words[1:] {
		if len(current)+1+len(w) > maxLineLen {
			lines = append(lines, current)
			current = continuationPrefix + w
		} else {
			current += " " + w
		}
	}
	lines = append(lines, current)
	return strings.Join(lines, "\n")
}
